import sys, os, json, tempfile, subprocess, shutil
# usage: t.py JSON spec {path: content}
def run(spec):
    d = tempfile.mkdtemp()
    for p, c in spec.items():
        f = os.path.join(d, p); os.makedirs(os.path.dirname(f), exist_ok=True)
        open(f, 'w').write(c)
    r = subprocess.run([sys.executable, '/work/repo/tools/packignore', d], capture_output=True, text=True)
    shutil.rmtree(d)
    return r.stdout.split('\n')[:-1] if r.returncode == 0 else 'ERR:' + r.stderr.strip()
if __name__ == '__main__':
    print(run(json.loads(sys.argv[1])))
